package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity @Table(name="rr_nomination_member",uniqueConstraints=@UniqueConstraint(name="uk_rr_nomination_member",columnNames={"agency_id","nomination_id","employee_no"}))
public class RrNominationMember extends RspAuditedEntity{@Column(name="nomination_id",nullable=false,length=36)private String nominationId;@Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="appointment_id",nullable=false)private Long appointmentId;@Column(name="business_unit_id")private Long businessUnitId;@Column(name="source_fingerprint",nullable=false,length=64)private String sourceFingerprint;@Column(name="display_order",nullable=false)private int displayOrder;protected RrNominationMember(){}public RrNominationMember(String a,String n,Long id,String no,String name,Long appt,Long bu,String fp,int order){super(a);nominationId=requiredText(n,"nominationId");employeeId=java.util.Objects.requireNonNull(id);employeeNo=requiredText(no,"employeeNo");employeeName=requiredText(name,"employeeName");appointmentId=java.util.Objects.requireNonNull(appt);businessUnitId=bu;sourceFingerprint=requiredText(fp,"sourceFingerprint");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getNominationId(){return nominationId;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public Long getAppointmentId(){return appointmentId;}public Long getBusinessUnitId(){return businessUnitId;}public String getSourceFingerprint(){return sourceFingerprint;}public int getDisplayOrder(){return displayOrder;}}
